  ('SUBS_MSISDN_UNIQUE', 1, 'Mobile service number is not reused across subscriptions', 'workspace.dq_triage.dq_mock_subs_c', 'PRIM_RSRC_VALU_TXT', 'CDE_CUST_MSISDN', 'uniqueness', 'count(*) OVER (PARTITION BY PRIM_RSRC_VALU_TXT) > 1', NULL, 'PRIM_RSRC_TYPE_KEY = 1 AND lower(trim(PRIM_RSRC_VALU_TXT)) <> \'service-number-unknown\'', 0.0, 'P1_block', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('SUBS_IMEI_NOT_NULL', 1, 'Handset IMEI is present', 'workspace.dq_triage.dq_mock_subs_c', 'IMEI_ID', 'CDE_DEVICE_IMEI', 'not_null', 'IMEI_ID IS NULL OR trim(IMEI_ID) = \'\'', NULL, NULL, 0.0, 'P3_monitor', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'v1 spelled the predicate out longhand. v2 calls dq.fn.is_blank_v1, the shared helper declared in sql/ddl/12_functions.sql. Identical counts on the same data -- sql/out/checkrun.sql was re-run against workspace.dq_triage before and after and every figure held. One definition instead of 8.'),
  ('SUBS_IMEI_NOT_NULL', 2, 'Handset IMEI is present', 'workspace.dq_triage.dq_mock_subs_c', 'IMEI_ID', 'CDE_DEVICE_IMEI', 'not_null', 'workspace.dq_triage.dq_fn_is_blank_v1(IMEI_ID)', NULL, NULL, 0.0, 'P3_monitor', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-07-19 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-07-19 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-07-19 03:00:00', 'MISSING SCOPE FILTER, DELIBERATELY. All 200 violations are Fixed Broadband. See COH-B.'),
  ('SUBS_SIM_NOT_NULL', 1, 'SIM serial is present for SIM-bearing products', 'workspace.dq_triage.dq_mock_subs_c', 'SIM_SERL_ID', 'CDE_SIM_SERIAL', 'not_null', 'SIM_SERL_ID IS NULL OR trim(SIM_SERL_ID) = \'\'', NULL, 'PROD_TYPE_KEY <> 0', 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'v1 spelled the predicate out longhand. v2 calls dq.fn.is_blank_v1, the shared helper declared in sql/ddl/12_functions.sql. Identical counts on the same data -- sql/out/checkrun.sql was re-run against workspace.dq_triage before and after and every figure held. One definition instead of 8.'),
  ('SUBS_SIM_NOT_NULL', 2, 'SIM serial is present for SIM-bearing products', 'workspace.dq_triage.dq_mock_subs_c', 'SIM_SERL_ID', 'CDE_SIM_SERIAL', 'not_null', 'workspace.dq_triage.dq_fn_is_blank_v1(SIM_SERL_ID)', NULL, 'PROD_TYPE_KEY <> 0', 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-07-19 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-07-19 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-07-19 03:00:00', 'The correctly-scoped twin of SUBS_IMEI_NOT_NULL. Same data, zero violations.'),
  ('SUBS_NTWK_NOT_NULL', 1, 'Network technology is populated', 'workspace.dq_triage.dq_mock_subs_c', 'NTWK_TECH_NM', 'CDE_NETWORK_TECH', 'not_null', 'NTWK_TECH_NM IS NULL OR trim(NTWK_TECH_NM) = \'\'', NULL, NULL, 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'v1 spelled the predicate out longhand. v2 calls dq.fn.is_blank_v1, the shared helper declared in sql/ddl/12_functions.sql. Identical counts on the same data -- sql/out/checkrun.sql was re-run against workspace.dq_triage before and after and every figure held. One definition instead of 8.'),
  ('SUBS_NTWK_NOT_NULL', 2, 'Network technology is populated', 'workspace.dq_triage.dq_mock_subs_c', 'NTWK_TECH_NM', 'CDE_NETWORK_TECH', 'not_null', 'workspace.dq_triage.dq_fn_is_blank_v1(NTWK_TECH_NM)', NULL, NULL, 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-07-19 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-07-19 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-07-19 03:00:00', 'Genuinely spread across all three product lines, so scope is not the explanation here.'),
  ('SUBS_PRIM_ACCT_NOT_ZERO', 1, 'Primary billing account is set', 'workspace.dq_triage.dq_mock_subs_c', 'PRIM_ACCT_KEY', 'CDE_BILLING_ACCOUNT', 'sentinel', 'PRIM_ACCT_KEY = 0', NULL, NULL, 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', 'MISSING SCOPE FILTER, DELIBERATELY. All 500 violations are prepaid. See COH-B.'),
  ('SUBS_BILL_OFFR_NOT_ZERO', 1, 'Main billing offer is set for postpaid', 'workspace.dq_triage.dq_mock_subs_c', 'MAIN_BILL_OFFR_KEY', 'CDE_BILL_OFFER', 'sentinel', 'MAIN_BILL_OFFR_KEY = 0', NULL, 'BILL_SUBS_TYPE_CD = \'POSTPAID\'', 0.0, 'P1_block', 'Billing', 'dq-stewards-billing', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('SUBS_ACTV_TS_CONSISTENT', 1, 'Original and initial activation timestamps agree', 'workspace.dq_triage.dq_mock_subs_c', 'ORIG_ACTV_TS', 'CDE_SUBS_ACTIVATION', 'consistency', 'ORIG_ACTV_TS <> INIT_ACTV_TS', NULL, NULL, 0.0, 'P3_monitor', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('SUBS_STTS_RSN_REQUIRED', 1, 'Non-active subscription carries a status reason', 'workspace.dq_triage.dq_mock_subs_c', 'SUBS_STTS_RSN_KEY', 'CDE_SUBS_STATUS', 'consistency', 'SUBS_STTS_RSN_KEY = 0 OR SUBS_STTS_RSN_KEY IS NULL', NULL, 'SUBS_STTS_KEY <> 1', 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('SUBS_KEY_UNIQUE', 1, 'Subscription key is unique', 'workspace.dq_triage.dq_mock_subs_c', 'SUBS_KEY', 'CDE_SUBS_KEY', 'uniqueness', 'count(*) OVER (PARTITION BY SUBS_KEY) > 1', NULL, NULL, 0.0, 'P1_block', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('SUBS_CLSE_TS_CONSISTENT', 1, 'Record close timestamp agrees with cancelled status', 'workspace.dq_triage.dq_mock_subs_c', 'ECF_CLSE_TS', 'CDE_RECORD_LIFECYCLE', 'consistency', '(ECF_CLSE_TS IS NOT NULL) <> (SUBS_STTS_KEY = 2)', NULL, NULL, 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('SUBS_BNFT_TXT_NOT_NULL', 1, 'Benefit text is populated', 'workspace.dq_triage.dq_mock_subs_c', 'BNFT_TXT', 'CDE_BENEFIT_TEXT', 'not_null', 'BNFT_TXT IS NULL OR trim(BNFT_TXT) = \'\'', NULL, NULL, 90.0, 'P3_monitor', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'v1 spelled the predicate out longhand. v2 calls dq.fn.is_blank_v1, the shared helper declared in sql/ddl/12_functions.sql. Identical counts on the same data -- sql/out/checkrun.sql was re-run against workspace.dq_triage before and after and every figure held. One definition instead of 8.'),
  ('SUBS_BNFT_TXT_NOT_NULL', 2, 'Benefit text is populated', 'workspace.dq_triage.dq_mock_subs_c', 'BNFT_TXT', 'CDE_BENEFIT_TEXT', 'not_null', 'workspace.dq_triage.dq_fn_is_blank_v1(BNFT_TXT)', NULL, NULL, 90.0, 'P3_monitor', 'Customer', 'dq-stewards-customer', 'L2', 'shadow', TIMESTAMP '2026-07-19 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-07-19 03:00:00', NULL, NULL, 'Shadow at a 90% threshold. 75% blank looks alarming but is probably an optional field. Left in shadow precisely because nobody has confirmed which -- promoting it on a hunch is how a queue fills with noise.'),
  ('XREF_SUBS_CTCT_ORPHAN', 1, 'Every subscription resolves to a contact', 'workspace.dq_triage.dq_mock_subs_c', NULL, 'CDE_CUST_KEY', 'referential', 'c.CTCT_KEY IS NULL', 'workspace.dq_triage.dq_mock_subs_c s LEFT JOIN workspace.dq_triage.dq_mock_ctct_c c ON s.CTCT_KEY = c.CTCT_KEY', NULL, 0.0, 'P1_block', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('XREF_NAME_AGREEMENT', 1, 'Subscriber first name agrees with contact first name', 'workspace.dq_triage.dq_mock_subs_c', NULL, 'CDE_CUST_NAME', 'consistency', 'lower(trim(s.SUBS_FRST_NM)) <> lower(trim(c.FRST_NM))', 'workspace.dq_triage.dq_mock_subs_c s JOIN workspace.dq_triage.dq_mock_ctct_c c ON s.CTCT_KEY = c.CTCT_KEY', NULL, 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', ''),
  ('XREF_OPEN_TS_AGREEMENT', 1, 'Subscription record open time agrees with contact add time', 'workspace.dq_triage.dq_mock_subs_c', NULL, 'CDE_RECORD_LIFECYCLE', 'consistency', 's.ECF_OPEN_TS <> c.CTCT_ADD_TS', 'workspace.dq_triage.dq_mock_subs_c s JOIN workspace.dq_triage.dq_mock_ctct_c c ON s.CTCT_KEY = c.CTCT_KEY', NULL, 0.0, 'P2_alert', 'Customer', 'dq-stewards-customer', 'L2', 'active', TIMESTAMP '2026-03-06 03:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-03-06 03:00:00', 'j.tanaka@example.com', TIMESTAMP '2026-03-06 03:00:00', '');
INSERT INTO workspace.dq_triage.dq_config_playbook
  (playbook_id, rule_id, rule_type, approach_name, approach_type, description, typical_owner, status, prior_use_count, recurrence_count, recurrence_rate, last_used_ts, created_by, created_at)
VALUES
  ('PB_UPSTREAM_SOURCE_RELEASE', NULL, 'format', 'Raise upstream ticket against the source release', 'upstream_ticket', 'Where a defect starts on a date that matches a source-system release, the correction belongs in that system. Raise a ticket against the release, attach the cohort\'s before/after counts, and hold the cohort open until the source ships. Do NOT correct the warehouse copy: while the source keeps emitting bad rows the warehouse would disagree with the system of record, which the spec rules out explicitly.', 'CRM Platform Team', 'active', 3, 0, 0.0, TIMESTAMP '2026-08-31 10:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-02-14 03:00:00'),
  ('PB_RULE_SCOPE_AMENDMENT', NULL, 'not_null', 'Amend the rule scope, not the data', 'accept_and_document', 'Where every violating row shares a product line or account type that legitimately does not carry the column, the rule is wrong, not the data. Reject the cohort with the reason recorded, then author a new rule version carrying the scope_filter and promote it through the registry. The rejection is the audit record that the rows were examined and found correct.', 'dq-stewards-customer', 'active', 0, 0, 0.0, NULL, 'm.okonkwo@example.com', TIMESTAMP '2026-02-14 03:00:00'),
  ('PB_PROVISIONING_BACKFILL', 'SUBS_MSISDN_SENTINEL', NULL, 'Route to provisioning for reissue', 'source_correction', 'A live service carrying a placeholder resource value cannot be corrected in the warehouse -- the real number does not exist anywhere yet. Route to provisioning to issue and publish the resource; the warehouse picks it up on the next load.', 'Provisioning Team', 'active', 2, 0, 0.0, TIMESTAMP '2026-08-25 10:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-02-14 03:00:00'),
  ('PB_PIPELINE_RERUN', NULL, 'consistency', 'Re-run the load for the affected window', 'pipeline_rerun', 'Where the source is correct and the warehouse copy is not, re-run the load for the affected partition window. Re-derives rather than amends, which is why this is the only class the spec flags as a candidate for assisted execution later.', 'Data Platform', 'active', 3, 0, 0.0, TIMESTAMP '2026-08-11 09:00:00', 'm.okonkwo@example.com', TIMESTAMP '2026-02-14 03:00:00'),
  ('PB_MANDATORY_FIELD_CAMPAIGN', NULL, 'not_null', 'Field-completion campaign with the owning channel', 'upstream_ticket', 'For genuinely absent attributes with no upstream defect, the fix is collection, not correction. Agree a completion target with the owning channel and track it as a deferred cohort with a review-by date rather than leaving it open.', 'Customer Operations', 'active', 0, 0, 0.0, NULL, 'm.okonkwo@example.com', TIMESTAMP '2026-02-14 03:00:00'),
  ('PB_ACCEPT_KNOWN_LIMITATION', NULL, 'variance', 'Accept and document a known source limitation', 'accept_and_document', 'Where a column is constant because the source system never populates it, and there is no plan to change that, record the acceptance with a reason so the cohort stops recurring silently. Revisit if the source system changes.', 'dq-stewards-customer', 'active', 0, 0, 0.0, NULL, 'm.okonkwo@example.com', TIMESTAMP '2026-02-14 03:00:00');
INSERT INTO workspace.dq_triage.dq_config_cde_registry
  (cde_id, cde_version, cde_name, business_term, data_class, definition, expected_signature, criticality, pii, regulatory_basis, tolerance_pct, bindings, business_domain, owner_group, status, effective_from, registered_by, registered_at, note)
VALUES
  ('CDE_CUST_EMAIL', 1, 'Customer email address', 'Customer contact email', 'email_address', 'The email address the business uses to reach a customer for servicing, billing and consent-bearing communications. Not a marketing preference and not an account login.', '^[^@\\s.]+(\\.[^@\\s.]+)*@[^@\\s.]+(\\.[^@\\s.]+)+$', 'high', TRUE, 'Privacy Act 1988 (Cth) APP 10 — quality of personal information', 0.5, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_ctct_c', 'target_column', 'EML_ID', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0), named_struct('target_table', 'workspace.dq_triage.dq_mock_ctct_c', 'target_column', 'EML_STTS_CD', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'The best-covered element in the register: nine active rules over two columns -- one composite and six specific on the address, two on the source\'s own status code. Registered as high rather than critical because an undeliverable address delays a communication; it does not misidentify a person.'),
  ('CDE_CUST_MSISDN', 1, 'Mobile service number (MSISDN)', 'Service number', 'msisdn', 'The mobile number a service is reachable on. Identifies the service to the network, to the customer and to every downstream system, which is why it is the one element here tiered critical on availability rather than on privacy.', '^04\\d{8}$', 'critical', TRUE, 'Telecommunications Consumer Protections Code C628 — service identification', 0.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'PRIM_RSRC_VALU_TXT', 'populated_when', 'the primary resource on the service is a mobile number', 'expected_scope_filter', 'PRIM_RSRC_TYPE_KEY = 1', 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'The column name says nothing — PRIM_RSRC_VALU_TXT holds whatever resource type the service uses. Only the data identifies it, which is why a register built from column names alone would have missed it entirely.'),
  ('CDE_CUST_DOB', 1, 'Customer date of birth', 'Date of birth', 'date_of_birth', 'The customer\'s date of birth as evidenced at onboarding. Used for identity verification, for age-gating, and for the credit assessment that a contract service depends on.', '^\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}$', 'high', TRUE, 'AML/CTF Act 2006 s.32 — KYC identity evidence', 0.5, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_ctct_c', 'target_column', 'BRTH_TS', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'The element where profiling earns its place on its own. The fourteen values written DD-MM-YYYY carry a different masked signature from the other 986, so they show up in top_signatures as a minority shape before any rule asserts anything about the column.'),
  ('CDE_CUST_NAME', 1, 'Customer name', 'Customer legal name', 'person_name', 'The name of the person the account is held by, as given on identity evidence. Three columns realise it: the full legal name and its parsed given and family components.', NULL, 'high', TRUE, 'AML/CTF Act 2006 s.32 — KYC identity evidence', 0.5, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_ctct_c', 'target_column', 'LEGL_NM', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0), named_struct('target_table', 'workspace.dq_triage.dq_mock_ctct_c', 'target_column', 'FRST_NM', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0), named_struct('target_table', 'workspace.dq_triage.dq_mock_ctct_c', 'target_column', 'LAST_NM', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'High criticality, and the only rule that touches it is a cross-table agreement check with no target_column — so a coverage view joining on columns alone would report zero rules on a KYC element and be wrong about why. That is what rule_registry.cde_id is for. Even counting it, all three bindings are watched by one consistency rule and nothing else: no format rule, no presence rule, no uniqueness. This is a real gap, left in place because reporting it is the point.'),
  ('CDE_CUST_IDENT_DOC', 1, 'Identity document number', 'Identity evidence document number', 'national_id', 'The number of the document presented as identity evidence at onboarding — passport, driver licence or equivalent, as typed in IDNT_TYPE_1_CD. The single most sensitive element in the register.', '^\\d{7}$', 'critical', TRUE, 'AML/CTF Act 2006 s.32 — KYC identity evidence; Privacy Act 1988 (Cth) APP 11', 0.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_ctct_c', 'target_column', 'IDNT_DOC_1_NO', 'populated_when', 'an identity document type has been recorded for the contact', 'expected_scope_filter', 'IDNT_TYPE_1_CD IS NOT NULL AND trim(IDNT_TYPE_1_CD) <> \'\'', 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'Critical, PII, KYC-bearing — and watched by exactly one rule, which only checks that the field is not empty. Nothing verifies the number is well formed for its document type, and nothing checks it is not shared between two people. The coverage panel classifies this \'unvalidated\' and it is the strongest argument in the register for having built the register.'),
  ('CDE_CUST_MOBILE', 1, 'Customer contact mobile number', 'Contact mobile', 'phone_number', 'The mobile number used to reach the person, as distinct from the MSISDN a service runs on. The two are frequently the same number and are not the same element — one is a contact detail, the other is a network resource.', '^04\\d{8}$', 'high', TRUE, 'Privacy Act 1988 (Cth) APP 10 — quality of personal information', 0.5, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_ctct_c', 'target_column', 'MOBL_NO', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', ''),
  ('CDE_CUST_LANDLINE', 1, 'Customer contact landline number', 'Contact landline', 'phone_number', 'The fixed-line number recorded against the contact, where one is held.', '^0\\d{9}$', 'medium', TRUE, 'Privacy Act 1988 (Cth) APP 10 — quality of personal information', 2.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_ctct_c', 'target_column', 'PHN_NO', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'Medium: a stale landline degrades reach, it does not misidentify or misbill.'),
  ('CDE_SIM_SERIAL', 1, 'SIM serial number', 'SIM serial', 'device_id', 'The serial of the SIM provisioned to a service. Identifies the SIM to the network and is the key to a replacement or port.', '^\\d{7}$', 'medium', FALSE, NULL, 2.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'SIM_SERL_ID', 'populated_when', 'services that carry a SIM — everything except fixed broadband', 'expected_scope_filter', 'PROD_TYPE_KEY <> 0', 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Subscription', 'dq-stewards-subscription', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'The correctly-scoped counterpart to IMEI below. Its rule carries the same scope_filter the binding declares, so the coverage view finds no mismatch — which is what makes the mismatch it does find on IMEI meaningful rather than an artefact of how the check is written.'),
  ('CDE_DEVICE_IMEI', 1, 'Device IMEI', 'Handset IMEI', 'device_id', 'The identity of the handset attached to a service. Only exists where the service involves a handset at all.', '^\\d{7}$', 'medium', FALSE, NULL, 2.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'IMEI_ID', 'populated_when', 'handset services only — fixed broadband has no handset and never will', 'expected_scope_filter', 'PROD_TYPE_KEY <> 0', 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Subscription', 'dq-stewards-subscription', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'COH-B, stated as a contradiction rather than as a discovery. The binding says this column is only populated for handset services. SUBS_IMEI_NOT_NULL carries no scope_filter and so measures every row, reporting 200 fixed-broadband services as defects. v_cde_coverage flags the rule by id. The rule is left unscoped on purpose — see CLAUDE.md; the register\'s job here is to show that the data is fine and the rule is not.'),
  ('CDE_BILLING_ACCOUNT', 1, 'Primary billing account', 'Billing account key', 'account_id', 'The billing account a service charges to. Postpaid services have one by definition; prepaid services do not have one at all.', '^\\d{7}$', 'high', FALSE, NULL, 0.5, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'PRIM_ACCT_KEY', 'populated_when', 'postpaid services only — a prepaid service has no billing account', 'expected_scope_filter', 'BILL_SUBS_TYPE_CD = \'POSTPAID\'', 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Subscription', 'dq-stewards-subscription', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'The second half of COH-B. SUBS_PRIM_ACCT_NOT_ZERO is unscoped and reports every prepaid service as a defect; the binding says prepaid never carries one. Its correctly-scoped twin SUBS_BILL_OFFR_NOT_ZERO checks a different column on the same rows and returns zero.'),
  ('CDE_CUST_KEY', 1, 'Customer record key', 'Customer key', 'account_id', 'The surrogate key of the contact record. Every subscription points at one; a key that is not unique or that a subscription cannot resolve is a broken customer, whatever else is right about the row.', '^\\d{7}$', 'critical', FALSE, NULL, 0.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_ctct_c', 'target_column', 'CTCT_KEY', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'Uniqueness by column match; the orphan check is cross-table, carries no target_column, and attaches by tag -- it is a rule about whether this key resolves, so this is its element.'),
  ('CDE_SUBS_KEY', 1, 'Subscription record key', 'Subscription key', 'account_id', 'The surrogate key of the subscription record.', '^\\d{7}$', 'critical', FALSE, NULL, 0.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'SUBS_KEY', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Subscription', 'dq-stewards-subscription', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', ''),
  ('CDE_VULNERABLE_CUSTOMER', 1, 'Vulnerable customer indicator', 'Special-care status', 'other', 'Whether the contact is recorded as needing special care -- financial hardship, accessibility, or another vulnerability the business must act on. A flag that is never set is a customer never protected.', '^[YN]$', 'critical', TRUE, 'Telecommunications Consumer Protections Code C628 — vulnerable customers and financial hardship', 0.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_ctct_c', 'target_column', 'SPCL_CARE_STTS', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'The pilot data reads \'N\' on all 1000 rows, and the variance rule that watches it says so. Whether that is a defaulted field or a population with no vulnerable customers is COH-F\'s open question.'),
  ('CDE_VULNERABLE_CUSTOMER', 2, 'Vulnerable customer indicator', 'Special-care status', 'other', 'Whether the contact is recorded as needing special care -- financial hardship, accessibility, or another vulnerability the business must act on. A flag that is never set is a customer never protected.', '^[YN]$', 'critical', TRUE, 'Telecommunications Consumer Protections Code C628 — vulnerable customers and financial hardship', 0.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_ctct_c', 'target_column', 'SPCL_CARE_STTS', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'retired', TIMESTAMP '2026-10-01 09:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-10-01 09:00:00', 'v2: retired 2026-10-01. Its only rule, CTCT_SPCL_CARE_VARIANCE, asked whether the flag ever varied, and on a 1000-row pilot extract an all-\'N\' column cannot tell a defaulted field from a population with no vulnerable customers -- so every run scored the element 0% for a question the data cannot answer. Retired with its rule rather than deleted. COH-F, raised on 2026-08-30 with that rule as a member, is left as raised. Re-register when the business can state how many customers it expects to carry the flag.'),
  ('CDE_PREF_LANGUAGE', 1, 'Preferred language', 'Contact language', 'other', 'The language the contact prefers to be served in.', NULL, 'low', FALSE, NULL, 5.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_ctct_c', 'target_column', 'PREF_LANG_NM', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'Its only rule is in shadow, so this element registers with no active rule against it -- the no_rule finding, present in the register on purpose.'),
  ('CDE_SUBS_STATUS', 1, 'Subscription status and reason', 'Subscription lifecycle status', 'other', 'Whether the subscription is active, cancelled or suspended, and why. The reason is only meaningful once the status is something other than active.', NULL, 'high', FALSE, NULL, 0.5, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'SUBS_STTS_KEY', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0), named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'SUBS_STTS_RSN_KEY', 'populated_when', 'the subscription is not active', 'expected_scope_filter', 'SUBS_STTS_KEY <> 1', 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Subscription', 'dq-stewards-subscription', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'Two bindings, one rule: the reason is checked, the status itself is not. The status binding is a no_rule finding until somebody writes one.'),
  ('CDE_SUBS_ACTIVATION', 1, 'Service activation timestamps', 'Activation date', 'other', 'When the service was first activated and when it was originally provisioned. The start of billing and of the contract term.', '^\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}$', 'high', FALSE, 'Telecommunications Consumer Protections Code C628 — billing accuracy', 0.5, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'ORIG_ACTV_TS', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0), named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'INIT_ACTV_TS', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Subscription', 'dq-stewards-subscription', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', ''),
  ('CDE_RECORD_LIFECYCLE', 1, 'Record lifecycle timestamps', 'Record open and close', 'other', 'When the subscription record was opened in the warehouse and, once cancelled, when it was closed. Agreement with the contact record\'s own timestamps is what says the two tables loaded from the same event.', '^\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}$', 'medium', FALSE, NULL, 2.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'ECF_OPEN_TS', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0), named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'ECF_CLSE_TS', 'populated_when', 'once the subscription is cancelled', 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Subscription', 'dq-stewards-subscription', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', ''),
  ('CDE_NETWORK_TECH', 1, 'Network technology', 'Access technology', 'other', 'The network the service runs on -- 4G, 5G, NBN and its variants.', NULL, 'medium', FALSE, NULL, 2.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'NTWK_TECH_NM', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Subscription', 'dq-stewards-subscription', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', ''),
  ('CDE_BILL_OFFER', 1, 'Main billing offer', 'Billing offer key', 'account_id', 'The offer a postpaid service is billed under. Prepaid services have none, for the same reason they have no billing account.', '^\\d{7}$', 'high', FALSE, 'Telecommunications Consumer Protections Code C628 — billing accuracy', 0.5, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'MAIN_BILL_OFFR_KEY', 'populated_when', 'postpaid services only', 'expected_scope_filter', 'BILL_SUBS_TYPE_CD = \'POSTPAID\'', 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Billing', 'dq-stewards-billing', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'The correctly-scoped counterpart to Primary billing account: its rule carries the scope the binding declares, so the coverage view finds no mismatch here and one there.'),
  ('CDE_BENEFIT_TEXT', 1, 'Benefit description', 'Plan benefit', 'other', 'Free-text description of the benefit attached to the plan, where one exists.', NULL, 'low', FALSE, NULL, 5.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'BNFT_TXT', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Subscription', 'dq-stewards-subscription', 'registered', TIMESTAMP '2026-02-14 03:00:00', 'r.delacruz@example.com', TIMESTAMP '2026-02-14 03:00:00', 'Registered so that its shadow rule names an element, as every rule must. Low: 75% blank is probably an optional field, which is exactly why the rule is still in shadow.');
